				y ? `${y} = ${vector}.y;` : null,
				z ? `${z} = ${vector}.z;` : null,
				w ? `${w} = ${vector}.w;` : null,
				r ? `${r} = ${vector}.r;` : null,
				g ? `${g} = ${vector}.g;` : null,
				b ? `${b} = ${vector}.b;` : null,
				a ? `${a} = ${vector}.a;` : null
